  ctx: CanvasRenderingContext2D,
  charStyle?: any,
  forMeasuring?: boolean,
) {
  ctx.textBaseline = 'alphabetic';
  if (this.path) {
    switch (this.pathAlign) {
      case CENTER:
        ctx.textBaseline = 'middle';
        break;
      case 'ascender':
        ctx.textBaseline = TOP;
        break;
