transformMatrixKey() {
  let skipGroup = arguments.length > 0 && arguments[0] !== undefined ? arguments[0] : false;
  let prefix = [];
  if (!skipGroup && this.group) {
    prefix = this.group.transformMatrixKey(skipGroup);
