translateToGivenOrigin(
  point: Point,
  fromOriginX: TOriginX,
  fromOriginY: TOriginY,
  toOriginX: TOriginX,
  toOriginY: TOriginY,
): Point {
  let x = point.x,
    y = point.y;
  const offsetX = resolveOrigin(toOriginX) - resolveOrigin(fromOriginX),
