import { createCanvas, loadImage } from 'canvas';
for (const f of ['bug_1','bug_2']) {
  const img = await loadImage(`/app/.harbor_assets/${f}.png`);
  const c = createCanvas(img.width, img.height);
  const ctx = c.getContext('2d');
  ctx.drawImage(img,0,0);
  const d = ctx.getImageData(0,0,img.width,img.height).data;
  let minX=1e9,maxX=-1,minY=1e9,maxY=-1,dark=0;
  const colHas=new Array(img.width).fill(0), rowHas=new Array(img.height).fill(0);
  for(let y=0;y<img.height;y++)for(let x=0;x<img.width;x++){
    const i=(y*img.width+x)*4; const lum=(d[i]+d[i+1]+d[i+2])/3;
    if(d[i+3]>10 && lum<128){dark++;minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y);colHas[x]++;rowHas[y]++;}
  }
  // find contiguous column clusters
  const cols=[]; let s=-1;
  for(let x=0;x<img.width;x++){ if(colHas[x]>0){if(s<0)s=x;}else{if(s>=0){cols.push([s,x-1]);s=-1;}}}
  if(s>=0)cols.push([s,img.width-1]);
  console.log(f, `size ${img.width}x${img.height}`, `dark=${dark}`, `xRange[${minX},${maxX}]`, `yRange[${minY},${maxY}]`, 'colClusters', JSON.stringify(cols));
}
