import fs from 'fs';
const SHA='6d4bf0db013b';
const all=JSON.parse(fs.readFileSync('/tmp/allfiles.json','utf8'));
// EVERYTHING textual, skip only known-huge/binary/env
const skip=/\.(png|jpg|jpeg|gif|webp|ico|woff2?|ttf|otf|eot|mp4|pdf)$/;
const cand=all.filter(f=>!skip.test(f) && f!=='package.json' && f!=='vitest.config.ts' && !f.startsWith('dist') && f!=='package-lock.json' && !f.startsWith('test/fixtures'));
const q=[...cand]; const mism=[]; let checked=0;
async function w(){while(q.length){const f=q.pop(); const local='/app/'+f;
  if(!fs.existsSync(local)){mism.push('MISSING '+f);continue;}
  try{const r=await fetch(`https://raw.githubusercontent.com/fabricjs/fabric.js/${SHA}/${f}`);
    if(!r.ok){mism.push('R'+r.status+' '+f);continue;}
    if((await r.text())!==fs.readFileSync(local,'utf8'))mism.push('DIFF '+f); checked++;
  }catch(e){mism.push('ERR '+f);}
}}
await Promise.all(Array.from({length:14},w));
console.log('checked',checked,'/',cand.length);
console.log(mism.join('\n'));
EOF
